:root {
  --pixel-bg: #0f0f1a;
  --pixel-panel: #1a1c2c;
  --pixel-border: #ffffff;
  --pixel-accent: #f4d03f;
  --pixel-text: #e0e0e0;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: var(--pixel-bg);
  font-family: monospace;
}
.quiz-panel {
  background: var(--pixel-panel);
  padding: 2rem;
  border: 4px solid var(--pixel-border);
  box-shadow: 8px 8px 0 #000;
  image-rendering: pixelated;
  max-width: 500px;
  width: 90%;
}
h1 {
  margin-top: 0;
  text-align: center;
  color: var(--pixel-accent);
  text-transform: uppercase;
  letter-spacing: 2px;
}
label {
  display: block;
  color: var(--pixel-text);
  margin-bottom: 0.5rem;
}
#question {
  background: #000;
  color: #fff;
  padding: 1rem;
  border: 3px solid var(--pixel-text);
  font-size: 1.5rem;
  text-align: center;
}
.answers,
.actions {
  display: flex;
  gap: 1rem;
  margin: 1rem 0;
}
button {
  font-family: inherit;
  font-size: 1.25rem;
  padding: 0.75rem 1.5rem;
  background: #3b3f5c;
  color: #fff;
  border: 3px solid #fff;
  box-shadow: 4px 4px 0 #000;
  cursor: pointer;
  text-transform: uppercase;
}
button:hover:not(:disabled) {
  background: #4e5473;
}
button:focus-visible {
  outline: 3px solid var(--pixel-accent);
  outline-offset: 2px;
}
button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  box-shadow: none;
  transform: translate(4px, 4px);
}
.score-block {
  display: flex;
  align-items: center;
  gap: 1rem;
  color: var(--pixel-text);
}
#score {
  font-size: 2rem;
  color: var(--pixel-accent);
}

const question = document.getElementById('question');
const answerA = document.getElementById('answer-a');
const answerB = document.getElementById('answer-b');
const nextButton = document.getElementById('next');
const restartButton = document.getElementById('restart');
const scoreOutput = document.getElementById('score');

const questions = [
  { text: '2 + 2 = ?', a: '4', b: '5', correct: '4' },
  { text: '3 + 3 = ?', a: '5', b: '6', correct: '6' }
];

const state = { current: 0, score: 0, answered: false };

function render() {
  const q = questions[state.current];
  if (!q) {
    question.textContent = 'Finished';
    answerA.disabled = true;
    answerB.disabled = true;
    nextButton.disabled = true;
    scoreOutput.textContent = state.score;
    return;
  }

  question.textContent = q.text;
  answerA.textContent = q.a;
  answerB.textContent = q.b;
  answerA.disabled = state.answered;
  answerB.disabled = state.answered;
  nextButton.disabled = !state.answered;
  scoreOutput.textContent = state.score;
}

function chooseAnswer(value) {
  if (state.answered || !questions[state.current]) {
    return;
  }
  state.answered = true;
  if (value === questions[state.current].correct) {
    state.score += 1;
  }
  render();
}

answerA.addEventListener('click', function () {
  chooseAnswer(answerA.textContent);
});

answerB.addEventListener('click', function () {
  chooseAnswer(answerB.textContent);
});

nextButton.addEventListener('click', function () {
  if (!state.answered || !questions[state.current]) {
    return;
  }
  state.current += 1;
  state.answered = false;
  render();
});

restartButton.addEventListener('click', function () {
  state.current = 0;
  state.score = 0;
  state.answered = false;
  render();
});

render();
